package br.com.cineo;
import android.app.*;import android.content.*;import android.net.Uri;import android.widget.*;import android.view.*;import org.json.*;import java.io.*;import java.util.*;import static br.com.cineo.MainActivity.*;
/** Foreground queue. URI permissions and stable upload IDs survive app restarts. */
class UploadQueue {
 final MainActivity a;JSONObject selectedShow,returnShow;int season=1,chapter=1,capacity=1000,queuePage=0;String selectionAccount="",selectionViewer="";boolean running=false;String owner="";TextView progress;
 UploadQueue(MainActivity activity){a=activity;}
 JSONArray rows(){try{return new JSONArray(a.prefs.getString(a.local("upload_queue"),"[]"));}catch(Exception ex){return new JSONArray();}}
 void save(JSONArray rows){a.prefs.edit().putString(a.local("upload_queue"),rows.toString()).apply();}
 void form(JSONObject show){a.page("upload-queue-form","Enviar uma sequência",show.optString("title"),3,()->a.pro.studio(show));selectedShow=show;returnShow=null;selectionAccount=a.uid;selectionViewer=a.viewerToken;capacity=1000;EditText s=a.field(a.body,"TEMPORADA","1",false),c=a.field(a.body,"PRIMEIRO CAPÍTULO","1",false);s.setInputType(2);c.setInputType(2);s.setText(String.valueOf(season));c.setText(String.valueOf(chapter));a.text(a.body,"Escolha vários MP4 de até 25 MB. Confira a ordem dos capítulos na fila antes de iniciar. Mantenha o aplicativo aberto durante o envio.",14,MUTED);a.button(a.body,"Selecionar vídeos",RED,()->a.safe(()->{season=Integer.parseInt(s.getText().toString());chapter=Integer.parseInt(c.getText().toString());if(season<1||chapter<1||chapter>1000)throw new IOException("Use números maiores que zero.");Intent intent=new Intent(Intent.ACTION_OPEN_DOCUMENT);intent.addCategory(Intent.CATEGORY_OPENABLE);intent.setType("video/mp4");intent.putExtra(Intent.EXTRA_ALLOW_MULTIPLE,true);a.startActivityForResult(intent,33);}));a.button(a.body,"Ver fila de envios",CARD,()->screen());}
 boolean result(int req,int res,Intent data){if(req!=33)return false;if(res!=Activity.RESULT_OK||data==null)return true;if(selectedShow==null||!selectionAccount.equals(a.uid)||!selectionViewer.equals(a.viewerToken)){a.notice("A conta ou o perfil mudou. Selecione os arquivos novamente.",true);return true;}a.safe(()->{JSONArray queue=rows();ArrayList<Uri> uris=new ArrayList<>();if(data.getClipData()!=null){for(int i=0;i<data.getClipData().getItemCount();i++)uris.add(data.getClipData().getItemAt(i).getUri());}else if(data.getData()!=null)uris.add(data.getData());int pending=0;for(int i=0;i<queue.length();i++){JSONObject row=queue.getJSONObject(i);if(row.optInt("show_id")==selectedShow.optInt("id")&&!row.optString("status").equals("done")){pending++;if(row.optInt("season",1)==season)chapter=Math.max(chapter,row.optInt("episode_number")+1);}}if(uris.size()+pending>capacity||chapter+uris.size()-1>1000)throw new IOException("A produção aceita até 1.000 capítulos. Reduza a seleção e confira os envios pendentes.");for(Uri uri:uris){try{a.getContentResolver().takePersistableUriPermission(uri,Intent.FLAG_GRANT_READ_URI_PERMISSION);}catch(SecurityException ignored){}String name="Capítulo "+chapter;try(android.database.Cursor cursor=a.getContentResolver().query(uri,new String[]{android.provider.OpenableColumns.DISPLAY_NAME},null,null,null)){if(cursor!=null&&cursor.moveToFirst())name=cursor.getString(0).replaceFirst("(?i)\\.mp4$","");}if(name.trim().isEmpty())name="Capítulo "+chapter;queue.put(a.obj("upload_id",UUID.randomUUID().toString(),"show_id",selectedShow.getInt("id"),"show_title",selectedShow.optString("title"),"uri",uri.toString(),"season",season,"episode_number",chapter++,"title",name.substring(0,Math.min(100,name.length())),"status","pending","error",""));}save(queue);queuePage=Math.max(0,(queue.length()-1)/20);screen();});return true;}

 void screen(){a.page("upload-queue","Fila de envios","Os capítulos só são publicados após a aprovação necessária.",3,()->{if(returnShow!=null)a.publisher.resume(returnShow,1);else a.profile();});if(returnShow!=null)a.button(a.body,"Voltar à produção",CARD,()->a.publisher.resume(returnShow,1));a.text(a.body,running?"Envio em andamento. Mantenha o Cineo aberto.":"Confira a numeração e toque em Iniciar. Você pode repetir apenas os arquivos que falharam.",14,MUTED);progress=a.text(a.body,"",14,MUTED);JSONArray queue=rows();if(queue.length()==0)a.empty(a.body,"film","Sua fila está vazia","Escolha vários episódios no estúdio da produção.");queuePage=Math.max(0,Math.min(queuePage,Math.max(0,(queue.length()-1)/20)));for(int i=queuePage*20;i<Math.min(queue.length(),(queuePage+1)*20);i++){final int index=i;JSONObject row=queue.optJSONObject(i);a.title(a.body,"T"+row.optInt("season")+" · EP "+row.optInt("episode_number")+" — "+row.optString("title"),16);a.text(a.body,row.optString("show_title")+"\n"+state(row.optString("status"))+" "+row.optString("error"),12,MUTED);if(!running&&!row.optString("status").equals("done")){a.button(a.body,"Editar título e número",CARD,()->edit(index));a.button(a.body,"Cancelar este envio",CARD,()->a.safe(()->{JSONArray rows=rows();rows.remove(index);save(rows);screen();}));}}if(queue.length()>20){LinearLayout pages=a.row();if(queuePage>0)a.button(pages,"Anterior",CARD,()->{queuePage--;screen();});if((queuePage+1)*20<queue.length())a.button(pages,"Próximos envios",CARD,()->{queuePage++;screen();});a.body.addView(pages);}if(!running)a.button(a.body,"Iniciar / tentar falhas novamente",RED,()->start());else a.button(a.body,"Parar após o arquivo atual",CARD,()->{running=false;Toast.makeText(a,"A fila parará após este arquivo.",0).show();});}
 String state(String value){return value.equals("done")?"✓ Enviado":value.equals("failed")?"Falhou:":value.equals("uploading")?"Interrompido / em andamento":"Aguardando";}
 void edit(int index){JSONObject row=rows().optJSONObject(index);if(row==null)return;LinearLayout form=a.col();form.setPadding(a.dp(16),a.dp(12),a.dp(16),0);EditText title=a.field(form,"TÍTULO","",false),chapter=a.field(form,"CAPÍTULO","",false);title.setText(row.optString("title"));chapter.setInputType(2);chapter.setText(row.optString("episode_number"));new AlertDialog.Builder(a).setTitle("Organizar arquivo").setView(form).setNegativeButton("Cancelar",null).setPositiveButton("Salvar",(d,n)->a.safe(()->{int n=Integer.parseInt(chapter.getText().toString());if(n<1||n>1000||title.getText().toString().trim().isEmpty())throw new IOException("Use título e capítulo entre 1 e 1000.");JSONArray queue=rows();queue.getJSONObject(index).put("upload_id",java.util.UUID.randomUUID().toString()).put("title",title.getText().toString()).put("episode_number",Integer.parseInt(chapter.getText().toString()));save(queue);screen();})).show();}
 void start(){if(running)return;JSONArray queue=rows();for(int i=0;i<queue.length();i++)try{if(queue.getJSONObject(i).optString("status").equals("failed-this-run"))queue.getJSONObject(i).put("status","failed");}catch(Exception ignored){}save(queue);running=true;owner=a.uid;screen();next();}
 void next(){if(!running||!owner.equals(a.uid))return;JSONArray queue=rows();int found=-1;for(int i=0;i<queue.length();i++)if(!queue.optJSONObject(i).optString("status").equals("done")&&!queue.optJSONObject(i).optString("status").equals("failed-this-run")){found=i;break;}if(found<0){running=false;for(int i=0;i<queue.length();i++)try{if(queue.getJSONObject(i).optString("status").equals("failed-this-run"))queue.getJSONObject(i).put("status","failed");}catch(Exception ignored){}save(queue);if(a.screen.equals("upload-queue"))screen();return;}final int index=found;JSONObject row=queue.optJSONObject(index);try{row.put("status","uploading");save(queue);}catch(Exception ignored){}if(progress!=null)progress.setText("Preparando "+row.optString("title"));final String account=owner,viewer=a.viewerToken;a.io.execute(()->{String error="";try{Uri uri=Uri.parse(row.getString("uri"));ByteArrayOutputStream out=new ByteArrayOutputStream();try(InputStream in=a.getContentResolver().openInputStream(uri)){byte[] bytes=new byte[65536];int n;while((n=in.read(bytes))!=-1){if(out.size()+n>26214400)throw new IOException("MP4 acima de 25 MB.");out.write(bytes,0,n);}}JSONObject payload=new JSONObject(row.toString());int seconds=0;android.media.MediaMetadataRetriever metadata=new android.media.MediaMetadataRetriever();try{metadata.setDataSource(a,uri);String duration=metadata.extractMetadata(android.media.MediaMetadataRetriever.METADATA_KEY_DURATION);if(duration!=null)seconds=(int)(Long.parseLong(duration)/1000);}catch(Exception ignored){}finally{metadata.release();}payload.put("duration_seconds",seconds);a.requestViewer.set(viewer);a.readFlow.ensureSession(account);byte[] original=out.toByteArray();payload.remove("video");payload.put("total",original.length);byte[] hash=java.security.MessageDigest.getInstance("SHA-256").digest(original);StringBuilder fingerprint=new StringBuilder();for(byte value:hash)fingerprint.append(String.format(java.util.Locale.US,"%02x",value&255));payload.put("fingerprint",fingerprint.toString());JSONObject started=a.request("POST","/v7/uploads/start",payload,a.token);if(started.optInt("episode_id")==0){java.util.HashSet<Integer> received=new java.util.HashSet<>();JSONArray existing=started.optJSONArray("parts");if(existing!=null)for(int i=0;i<existing.length();i++)received.add(existing.optJSONObject(i).optInt("part"));int count=(original.length+2097151)/2097152;for(int part=0;part<count;part++){if(!account.equals(a.uid))throw new IOException("Conta alterada durante o envio.");if(!received.contains(part)){byte[] chunk=java.util.Arrays.copyOfRange(original,part*2097152,Math.min(original.length,(part+1)*2097152));a.request("POST","/v7/uploads/"+row.getString("upload_id")+"/part",a.obj("part",part,"bytes",android.util.Base64.encodeToString(chunk,2)),a.token);}final int percent=(part+1)*100/count;a.runOnUiThread(()->{if(account.equals(a.uid)&&a.screen.equals("upload-queue")&&progress!=null)progress.setText("Enviando "+row.optString("title")+" · "+percent+"%");});}a.request("POST","/v7/uploads/"+row.getString("upload_id")+"/finish",new JSONObject(),a.token);}}catch(Exception ex){error=ex.getMessage()==null?"Falha de conexão":ex.getMessage();}finally{a.requestViewer.remove();}String failure=error;a.runOnUiThread(()->{if(a.isDestroyed()||!account.equals(a.uid)){running=false;return;}try{JSONArray current=rows();for(int i=0;i<current.length();i++){JSONObject item=current.getJSONObject(i);if(item.optString("upload_id").equals(row.optString("upload_id"))){item.put("status",failure.isEmpty()?"done":"failed-this-run").put("error",failure);break;}}save(current);}catch(Exception ignored){}if(a.screen.equals("upload-queue"))screen();if(running)next();});});}
}
